#include <stdio.h>
#include <stdlib.h>

int *loadValues(const char *path, int *outCount) {
    FILE *fp = fopen(path, "r");
    if (fp == NULL) {                  // check return value
        *outCount = 0;
        return NULL;
    }

    int count = 0;
    if (fscanf(fp, "%d", &count) != 1 || count <= 0) {   // validate input
        fclose(fp);
        *outCount = 0;
        return NULL;
    }

    int *values = malloc(count * sizeof(int));
    if (values == NULL) {              // check allocation
        fclose(fp);
        *outCount = 0;
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        if (fscanf(fp, "%d", &values[i]) != 1) {
            free(values);               // clean up on the error path too
            fclose(fp);
            *outCount = 0;
            return NULL;
        }
    }

    fclose(fp);
    *outCount = count;
    return values;
}
